import { type } from "arktype"

// add: (a: number, b: number) => number
export const add = type.fn("number", "number", ":", "number")(
  (a, b) => a + b
)

// subtract: (a: number, b: number) => number
export const subtract = type.fn("number", "number", ":", "number")(
  (a, b) => a - b
)

// multiply: (a: number, b: number) => number
export const multiply = type.fn("number", "number", ":", "number")(
  (a, b) => a * b
)

// divide: divisor must be non-zero
// "number != 0" expresses a number that is not equal to 0 in ArkType
export const divide = type.fn("number", "number != 0", ":", "number")(
  (a, b) => a / b
)

// modulo: divisor must be a non-zero integer
// "integer != 0" expresses an integer that is not equal to 0
export const modulo = type.fn("number", "integer != 0", ":", "number")(
  (a, b) => a % b
)

// compute dispatcher: op is constrained to the literal union of operation names
export const compute = type.fn(
  "'add' | 'subtract' | 'multiply' | 'divide' | 'modulo'",
  "number",
  "number",
  ":",
  "number"
)(
  (op, a, b) => {
    switch (op) {
      case "add":      return add(a, b)
      case "subtract": return subtract(a, b)
      case "multiply": return multiply(a, b)
      case "divide":   return divide(a, b)
      case "modulo":   return modulo(a, b)
    }
  }
)

import { TraversalError } from "arktype"
import { compute } from "./src/engine.ts"

const raw = await new Promise<string>((resolve) => {
  let data = ""
  process.stdin.setEncoding("utf8")
  process.stdin.on("data", (chunk) => { data += chunk })
  process.stdin.on("end", () => { resolve(data) })
})

const input = JSON.parse(raw.trim()) as { op: unknown; a: unknown; b: unknown }

try {
  const result = compute(input.op as never, input.a as never, input.b as never)
  process.stdout.write(`OK ${result}\n`)
} catch (err) {
  if (err instanceof TraversalError) {
    process.stdout.write(`ERR ${err.message}\n`)
  } else {
    throw err
  }
}

process.exit(0)

